function FAQ({items}){const [open,setOpen]=useState(0);return <div className="faq-list">{items.map(([q,a],i)=><div className="faq-item" key={q}><button type="button" onClick={()=>setOpen(open===i?-1:i)} aria-expanded={open===i}>{q}<ChevronDown className={open===i?'rotated':''} size={18}/></button><AnimatePresence initial={false}>{open===i&&<motion.p initial={{height:0,opacity:0}} animate={{height:'auto',opacity:1}} exit={{height:0,opacity:0}}>{a}</motion.p>}</AnimatePresence></div>)}</div>}
